package net.civeira.phylax.features.oauth.authentication.infrastructure.driver.rest;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.core.Context;
import jakarta.ws.rs.core.HttpHeaders;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.MultivaluedMap;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.features.oauth.client.application.ClientAuthenticator;
import net.civeira.phylax.features.oauth.client.domain.ClientAuthPolicy;
import net.civeira.phylax.features.oauth.client.domain.ClientCredentials;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.device.application.DeviceAuthorizationService;
import net.civeira.phylax.features.oauth.device.domain.DeviceAuthorization;
import net.civeira.phylax.features.oauth.par.application.usecase.pushauthorization.PushAuthorizationParams;
import net.civeira.phylax.features.oauth.par.application.usecase.pushauthorization.PushAuthorizationResult;
import net.civeira.phylax.features.oauth.par.application.usecase.pushauthorization.PushAuthorizationUsecase;
import net.civeira.phylax.features.oauth.par.domain.exception.ParException;

/**
 * REST endpoints for device, PAR, and CIBA flows.
 *
 * Responsibilities: - Handle RFC 8628 device authorization requests (confidential or public
 * clients). - Handle PAR requests (confidential clients). - Expose a placeholder CIBA endpoint.
 *
 * Design notes: - Client authentication goes through {@link ClientAuthenticator}.
 */
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class DevicesAccessController {

  /**
   * Body parameters that authenticate the client: never stored with a pushed request.
   */
  private static final Set<String> CLIENT_CREDENTIAL_PARAMS =
      Set.of("client_secret", "client_assertion", "client_assertion_type");

  private final ClientAuthenticator clientAuthenticator;
  private final DeviceAuthorizationService deviceService;
  private final CurrentRequest current;
  private final PushAuthorizationUsecase pushAuthorizationUsecase;

  /**
   * Handles device authorization requests (RFC 8628 §3.1).
   *
   * Authenticates the client, creates a device authorization record, and returns device_code,
   * user_code, verification_uri, expires_in, and interval.
   *
   * @param tenant tenant identifier
   * @param headers HTTP request headers
   * @param paramMap request parameters
   * @return device authorization response or error
   */
  @POST
  @Path("oauth/openid/{tenant}/device")
  public Response device(final @PathParam("tenant") String tenant, @Context HttpHeaders headers,
      final MultivaluedMap<String, String> paramMap) {
    Optional<ClientDetails> clientOpt = clientAuthenticator.authenticate(tenant,
        ClientCredentials.from(headers.getHeaderString(HttpHeaders.AUTHORIZATION), paramMap),
        ClientAuthPolicy.SECRET_OR_PUBLIC);
    if (clientOpt.isEmpty()) {
      return errorResponse(401, "invalid_client", "Client authentication failed");
    }

    ClientDetails client = clientOpt.get();
    if (!client.allowedGrant(DeviceAuthorizationService.grantType())) {
      return errorResponse(400, "unauthorized_client", "Client not allowed to use device flow");
    }

    String scope = paramMap.getFirst("scope");
    List<String> audiences =
        paramMap.containsKey("audience") ? paramMap.get("audience") : List.of();

    DeviceAuthorization auth = deviceService.createAuthorization(tenant, client, scope, audiences);

    String verificationUri = current.getPublicHost() + "/oauth/openid/" + tenant + "/device/verify";

    Map<String, Object> body = new LinkedHashMap<>();
    body.put("device_code", auth.getDeviceCode());
    body.put("user_code", auth.getUserCode());
    body.put("verification_uri", verificationUri);
    body.put("verification_uri_complete", verificationUri + "?user_code=" + auth.getUserCode());
    body.put("expires_in", auth.expiresInSeconds());
    body.put("interval", auth.getInterval());

    return Response.ok(body).build();
  }

  /**
   * Handles pushed authorization requests (PAR) — RFC 9126 §2.
   *
   * Authenticates the client via client_secret_basic or client_secret_post, validates the
   * authorization parameters, stores the PAR, and returns request_uri + expires_in.
   *
   * @param tenant tenant identifier
   * @param headers HTTP request headers (used for Basic auth)
   * @param paramMap request body parameters
   * @return 201 with request_uri/expires_in, or 400/401 on error
   */
  @POST
  @Path("oauth/openid/{tenant}/par-request")
  public Response par(final @PathParam("tenant") String tenant, @Context HttpHeaders headers,
      final MultivaluedMap<String, String> paramMap) {
    Map<String, String> authParams = new LinkedHashMap<>();
    for (Map.Entry<String, List<String>> entry : paramMap.entrySet()) {
      if (!entry.getValue().isEmpty() && !CLIENT_CREDENTIAL_PARAMS.contains(entry.getKey())) {
        authParams.put(entry.getKey(), entry.getValue().get(0));
      }
    }

    try {
      PushAuthorizationParams params = PushAuthorizationParams.builder().tenant(tenant)
          .credentials(
              ClientCredentials.from(headers.getHeaderString(HttpHeaders.AUTHORIZATION), paramMap))
          .authParams(authParams).build();
      PushAuthorizationResult result = pushAuthorizationUsecase.push(params);
      return Response.status(201)
          .entity(Map.of("request_uri", result.requestUri(), "expires_in", result.expiresIn()))
          .build();
    } catch (ParException ex) {
      return errorResponse(ex.getStatusCode(), ex.getError(), ex.getMessage());
    }
  }

  @POST
  @Path("oauth/openid/{tenant}/par")
  public Response parAlias(final @PathParam("tenant") String tenant, @Context HttpHeaders headers,
      final MultivaluedMap<String, String> paramMap) {
    return par(tenant, headers, paramMap);
  }

  /**
   * Handles CIBA authentication requests.
   *
   * Currently returns forbidden for all clients. Reserved for future CIBA support.
   *
   * @param tenant tenant identifier
   * @param paramMap request parameters
   * @return forbidden response
   */
  @POST
  @Path("oauth/openid/{tenant}/ciba-auth")
  public Response ciba(final @PathParam("tenant") String tenant,
      final MultivaluedMap<String, String> paramMap) {
    return Response.status(403, "Client not allowed.").build();
  }

  private Response errorResponse(int status, String error, String description) {
    Response.ResponseBuilder builder =
        Response.status(status).entity(Map.of("error", error, "error_description", description))
            .type(MediaType.APPLICATION_JSON).header("Cache-Control", "no-store");
    if (status == 401) {
      builder.header("WWW-Authenticate", "Basic realm=\"oauth\"");
    }
    return builder.build();
  }
}
